   166	    private void processCompleteOrder(Order order, User user, PayAndShipmentRequestDto requestDto) {
   167	        try {
   168	            log.info("전체 주문 처리 시작: 주문ID={}", order.getId());
   169	
   170	            // 1. 결제 처리
   171	            Payment payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
   172	            order.assignPayment(payment);
   173	
   174	            if (!payment.isSuccess()) {
   175	                throw new RuntimeException("결제 실패: " + payment.getStatus());
   176	            }
   177	
   178	            log.info("결제 처리 완료: 주문ID={}, 결제ID={}", order.getId(), payment.getId());
   179	
   180	            // 2. 배송 정보 생성
   181	            OrderShipment shipment = orderShipmentCommandService.createOrderShipment(
   182	                    order,
   183	                    requestDto.getReceiverName(),
   184	                    requestDto.getReceiverPhone(),
   185	                    requestDto.getPostalCode(),
   186	                    requestDto.getAddress()
   187	            );
   188	            order.assignOrderShipment(shipment);
   189	            log.info("배송 정보 생성 완료: 주문ID={}", order.getId());
   190	
   191	            // 3. 상태 업데이트 (OrderStatus enum 사용)
   192	            if (!order.getStatus().canTransitionTo(OrderStatus.PAYMENT_COMPLETED)) {
   193	                throw new RuntimeException("결제 완료 상태로 전환할 수 없습니다. 현재 상태: " + order.getStatus());
   194	            }
   195	            order.updateStatus(OrderStatus.PAYMENT_COMPLETED);
   196	
   197	            if (requestDto.isWarehouseStorage()) {
   198	                // 창고 보관일 경우
   199	                WarehouseStorage warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
   200	                order.assignWarehouseStorage(warehouseStorage);
   201	
   202	                // 상태 전환 검증
   203	                if (order.getStatus().canTransitionTo(OrderStatus.PREPARING)) {
   204	                    order.updateStatus(OrderStatus.PREPARING);
   205	                }
   206	                if (order.getStatus().canTransitionTo(OrderStatus.IN_WAREHOUSE)) {
   207	                    order.updateStatus(OrderStatus.IN_WAREHOUSE);
   208	                }
   209	                if (order.getStatus().canTransitionTo(OrderStatus.COMPLETED)) {
   210	                    order.updateStatus(OrderStatus.COMPLETED);
   211	                }
   212	
   213	                log.info("창고 보관 처리 완료: 주문ID={}", order.getId());
