            log.info("브라우저가 초기화되지 않았습니다. 자동으로 초기화합니다.");
            openBrowser();
        }

        try {
            log.debug("새 페이지 생성");
            return browser.newPage();
        } catch (Exception e) {
            log.error("새 페이지 생성 실패: {}", e.getMessage(), e);
            throw new ShipmentException(
                    ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR,
                    "새 페이지를 생성할 수 없습니다: " + e.getMessage(),
                    e
            );
        }
    }

